<script setup lang="tsx">
import type { WatchStopHandle } from "vue";
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips } from "@/util/tips";
import { GetCollectionRank } from "@/apis/collection.ts";
import type { CollectionRank, CollectionRankView } from "@/types/collection.ts";
import { JudgeStatus } from "@/apis/judge.ts";
import { GetAvatarUrl } from "@/util/avatar.ts";
import type { TableRowData, TNodeReturnValue } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

let watchHandle: WatchStopHandle | null = null;
let collectionId = 0;

let problemCount = 0;

// 说明：tdesign 的 BaseTableCol<T> 是递归类型（children?: BaseTableCol<T>[]），本页直接标注它会触发
// TS2589（Type instantiation is excessively deep），故按其字段构造一个非递归的等价列类型
type CollectionRankColumn = {
  title: string;
  colKey: string;
  align?: "left" | "right" | "center";
  cell?: (_h: unknown, data: CellParams<TableRowData>) => TNodeReturnValue;
};

const listColumns = ref<CollectionRankColumn[]>([
  {
    title: "Rank",
    colKey: "rank",
    align: "center",
  },
  {
    title: "序号",
    colKey: "index",
    align: "center",
  },
  {
    title: "昵称",
    colKey: "nickname",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const avatarUrl = GetAvatarUrl(data.row.username, data.row.email);
      return (
        <t-space>
          <t-avatar shape="round" size="32px" image={avatarUrl} hide-on-load-failed={false} />
          <t-button
            variant="text"
            onClick={() =>
              router.push({
                name: "user",
                params: { username: data.row.username },
              })
            }
          >
            {data.row.nickname}
          </t-button>
        </t-space>
      );
    },
  },
  {
    title: "Username",
    colKey: "username",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button
          variant="text"
          onClick={() =>
            router.push({
              name: "user",
              params: { username: data.row.username },
            })
          }
        >
          {data.row.username}
        </t-button>
      );
    },
  },
  {
    title: "Count",
    colKey: "count",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button
          variant="text"
          onClick={() =>
            router.push({
              name: "judge-list",
              query: {
                username: data.row.username,
                status: JudgeStatus.Accept,
              },
            })
          }
        >
          {`${data.row.accept} / ${problemCount}`}
        </t-button>
      );
    },
  },
  {
    title: "Progress",
    colKey: "progress",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      let percent = 100;
      if (problemCount > 0) {
        // 保留两位数字
        percent = Number(((data.row.accept / problemCount) * 100).toFixed(2));
      }
      if (isMobile.value) {
        return <span>{percent}%</span>;
      }
      return <t-progress percentage={percent} />;
    },
  },
]);

const visibleColumns = computed<CollectionRankColumn[]>(() => {
  if (isMobile.value) {
    return listColumns.value.filter((col) => col.colKey !== "username");
  }
  return listColumns.value;
});

const dataLoading = ref(false);

const collectionRankViews = ref<CollectionRankView[]>([]);
const rowspanAndColspan = ({ col, rowIndex }: CellParams<TableRowData>) => {
  let rowspan = 1;
  for (let i = rowIndex + 1; i < collectionRankViews.value.length; i++) {
    if (collectionRankViews.value[i].rank === collectionRankViews.value[rowIndex].rank) {
      rowspan++;
    } else {
      break;
    }
  }
  if (col.colKey === "rank") {
    return {
      rowspan: rowspan,
    };
  }
};

const fetchData = async (needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  try {
    const res = await GetCollectionRank(collectionId);
    collectionRankViews.value = [];
    if (res.code === 0) {
      problemCount = res.data.problem;
      const responseList = res.data.ranks as CollectionRank[];
      const results = [];
      if (responseList) {
        for (let i = 0; i < responseList.length; i++) {
          const item = responseList[i];
          const result = {
            userId: item.inserter,
            username: item.inserter_username,
            nickname: item.inserter_nickname,
            email: item.inserter_email,
          } as CollectionRankView;
          result.accept = item.accept;
          results.push(result);
        }
        results.sort((a: CollectionRankView, b: CollectionRankView) => {
          if (a.accept !== b.accept) {
            return b.accept - a.accept; // 降序
          }
          return a.userId - b.userId; // 升序
        });
        let rank = 0;
        let lastAccept = -1;
        for (let i = 0; i < results.length; i++) {
          if (results[i].accept !== lastAccept) {
            rank = i + 1; // 更新排名
            lastAccept = results[i].accept;
          }
          results[i].index = i + 1;
          results[i].rank = rank;
        }
      }
      collectionRankViews.value = results;
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
  }
};

// 初始化分页信息
onMounted(async () => {
  watchHandle = watch(
    () => route.query,
    async () => {
      if (Array.isArray(route.params.collectionId)) {
        collectionId = Number(route.params.collectionId[0]);
      } else {
        collectionId = Number(route.params.collectionId);
      }
      if (!collectionId) {
        await router.push({ name: "problem-collection-list" });
        return;
      }
      await fetchData(true);
    },
    { immediate: true }
  );
});

onBeforeUnmount(() => {
  if (watchHandle) {
    watchHandle();
  }
});
</script>

<template>
  <t-row>
    <t-card style="margin: 10px">
      <div style="overflow-x: auto; width: 100%">
        <t-table
          :data="collectionRankViews"
          :columns="visibleColumns"
          row-key="index"
          :rowspan-and-colspan="rowspanAndColspan"
          vertical-align="middle"
          :bordered="true"
          :hover="true"
          :loading="dataLoading"
          :size="isMobile ? 'small' : 'medium'"
        />
      </div>
    </t-card>
  </t-row>
</template>

<style scoped></style>
